async function fetchWithRetry(request, retries = 3) {
  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      const response = await request();

      return response;
    } catch (error) {
      console.log(`Attempt ${attempt} failed`);

      if (attempt === retries) {
        throw error;
      }
    }
  }
}

